//
// Produces a tree of tagged nodes:
//   { type: 'table', map: Map<string, Node>, path: string[], headered: bool }
//   { type: 'array-table', items: Node[] }        // items are 'table' nodes
//   { type: 'array', items: Node[] }
//   { type: 'string', value: string }
//   { type: 'integer', value: BigInt }
//   { type: 'float', value: number }
//   { type: 'boolean', value: boolean }

export class ParseError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.isParseError = true
    this.line = line
    this.reason = reason
  }
}

function mkErr(line, reason) {
  return new ParseError(line, reason)
}

function renderPath(path) {
  return path.join('.')
}

function compareCodePoints(a, b) {
  const ca = Array.from(a)
  const cb = Array.from(b)
  const len = Math.min(ca.length, cb.length)
  for (let i = 0; i < len; i++) {
    const pa = ca[i].codePointAt(0)
    const pb = cb[i].codePointAt(0)
    if (pa !== pb) return pa - pb
  }
  return ca.length - cb.length
}

class LineParser {
  constructor(line, lineNo) {
    this.line = line
    this.pos = 0
    this.lineNo = lineNo
  }

  atEnd() {
    return this.pos >= this.line.length
  }

  peek() {
    return this.line[this.pos]
  }

  skipWS() {
    while (!this.atEnd() && (this.peek() === ' ' || this.peek() === '\t')) this.pos++
  }

  skipWSAndComment() {
    this.skipWS()
    if (!this.atEnd() && (this.peek() === '#' || this.peek() === ';')) {
      this.pos = this.line.length
    }
  }
}

const INTEGER_RE = /^[+-]?[0-9](_?[0-9])*$/
const FLOAT_RE = /^[+-]?[0-9](_?[0-9])*(\.[0-9](_?[0-9])*([eE][+-]?[0-9](_?[0-9])*)?|[eE][+-]?[0-9](_?[0-9])*)$/

function normalizeInt(word) {
  let w = word.replace(/_/g, '')
  if (w[0] === '+') w = w.slice(1)
  return BigInt(w)
}

function isStopChar(ch) {
  return ch === ' ' || ch === '\t' || ch === ',' || ch === ']' || ch === '}'
}

function parseBasicString(lp) {
  // assumes lp.peek() === '"'
  lp.pos++
  let result = ''
  while (true) {
    if (lp.atEnd()) throw mkErr(lp.lineNo, 'unterminated string')
    const c = lp.line[lp.pos]
    if (c === '"') {
      lp.pos++
      return result
    }
    if (c === '\\') {
      lp.pos++
      if (lp.atEnd()) throw mkErr(lp.lineNo, 'unterminated string')
      const e = lp.line[lp.pos]
      switch (e) {
        case '"':
          result += '"'
          lp.pos++
          break
        case '\\':
          result += '\\'
          lp.pos++
          break
        case 'n':
          result += '\n'
          lp.pos++
          break
        case 't':
          result += '\t'
          lp.pos++
          break
        case 'r':
          result += '\r'
          lp.pos++
          break
        case '0':
          result += '\0'
          lp.pos++
          break
        case 'u': {
          const hexStart = lp.pos + 1
          if (hexStart + 4 > lp.line.length) throw mkErr(lp.lineNo, 'unterminated string')
          const hex = lp.line.slice(hexStart, hexStart + 4)
          if (!/^[0-9a-fA-F]{4}$/.test(hex)) throw mkErr(lp.lineNo, 'invalid escape \\u')
          result += String.fromCharCode(parseInt(hex, 16))
          lp.pos = hexStart + 4
          break
        }
        default:
          throw mkErr(lp.lineNo, `invalid escape \\${e}`)
      }
      continue
    }
    result += c
    lp.pos++
  }
}

function parseLiteralString(lp) {
  // assumes lp.peek() === "'"
  lp.pos++
  let result = ''
  while (true) {
    if (lp.atEnd()) throw mkErr(lp.lineNo, 'unterminated string')
    const c = lp.line[lp.pos]
    if (c === "'") {
      lp.pos++
      return result
    }
    result += c
    lp.pos++
  }
