function parseName(lp) {
  if (lp.atEnd()) throw mkErr(lp.lineNo, 'expected a name')
  const c = lp.peek()
  if (c === '"') return parseBasicString(lp)
  if (c === "'") return parseLiteralString(lp)
  const start = lp.pos
  while (!lp.atEnd() && /[A-Za-z0-9_-]/.test(lp.peek())) lp.pos++
  if (lp.pos === start) throw mkErr(lp.lineNo, 'expected a name')
  return lp.line.slice(start, lp.pos)
