function parseDottedName(lp) {
  const names = []
  while (true) {
    lp.skipWSAndComment()
    const name = parseName(lp)
    names.push(name)
    lp.skipWSAndComment()
    if (!lp.atEnd() && lp.peek() === '.') {
      lp.pos++
      lp.skipWSAndComment()
      continue
    }
    break
  }
  return names
