  lp.skipWSAndComment()
  if (lp.atEnd()) throw mkErr(lp.lineNo, 'expected a value')
  const c = lp.peek()
  if (c === '"') return { type: 'string', value: parseBasicString(lp) }
  if (c === "'") return { type: 'string', value: parseLiteralString(lp) }
  if (c === '[') return parseArray(lp)
  if (c === '{') return parseInlineTable(lp, pathPrefix)
  const start = lp.pos
  while (!lp.atEnd() && !isStopChar(lp.peek())) lp.pos++
  const word = lp.line.slice(start, lp.pos)
  if (word === 'true') return { type: 'boolean', value: true }
  if (word === 'false') return { type: 'boolean', value: false }
