    lp.pos++
    return { type: 'array', items }
  }
  while (true) {
    const v = parseValue(lp, [])
    items.push(v)
    lp.skipWSAndComment()
    if (lp.atEnd()) throw mkErr(lp.lineNo, 'unterminated array')
