function assignDotted(container, names, value, lineNo) {
  let t = container
  let path = container.path
  for (let i = 0; i < names.length - 1; i++) {
    const name = names[i]
    path = path.concat(name)
    const entry = t.map.get(name)
    if (entry === undefined) {
      const nt = { type: 'table', map: new Map(), path, headered: false }
      t.map.set(name, nt)
      t = nt
    } else if (entry.type === 'table') {
      t = entry
    } else if (entry.type === 'array-table') {
      t = entry.items[entry.items.length - 1]
    } else {
