  if (lp.peek() === '}') {
    lp.pos++
    return table
  }
  while (true) {
    lp.skipWSAndComment()
    if (lp.atEnd()) throw mkErr(lp.lineNo, 'unterminated inline table')
    const names = parseDottedName(lp)
    lp.skipWSAndComment()
    if (lp.atEnd() || lp.peek() !== '=') throw mkErr(lp.lineNo, 'expected = in an inline table')
    lp.pos++
    lp.skipWSAndComment()
