    if (entry === undefined) {
      const at = { type: 'array-table', items: [] }
      table.map.set(last, at)
      const item = { type: 'table', map: new Map(), path: finalPath, headered: false }
      at.items.push(item)
      state.current = item
    } else if (entry.type === 'array-table') {
      const item = { type: 'table', map: new Map(), path: finalPath, headered: false }
      entry.items.push(item)
      state.current = item
    } else {
      throw mkErr(lineNo, `${renderPath(finalPath)} is not an array of tables`)
    }
