    const names = parseDottedName(lp)
    lp.skipWSAndComment()
    if (lp.atEnd() || lp.peek() !== ']') throw mkErr(lineNo, 'unterminated table header')
    lp.pos++
    if (isArray) {
      if (lp.atEnd() || lp.peek() !== ']') throw mkErr(lineNo, 'unterminated table header')
      lp.pos++
    }
    lp.skipWSAndComment()
    if (!lp.atEnd()) throw mkErr(lineNo, 'trailing text after a table header')
