      const nt = { type: 'table', map: new Map(), path: finalPath, headered: true }
      table.map.set(last, nt)
      state.current = nt
    } else if (entry.type === 'table') {
      if (entry.headered) throw mkErr(lineNo, `table ${renderPath(finalPath)} is defined twice`)
      entry.headered = true
      state.current = entry
    } else {
      throw mkErr(lineNo, `${renderPath(finalPath)} is not a table`)
    }
  } else {
    if (entry === undefined) {
      const at = { type: 'array-table', items: [] }
      table.map.set(last, at)
      const item = { type: 'table', map: new Map(), path: finalPath, headered: false }
      at.items.push(item)
      state.current = item
    } else if (entry.type === 'array-table') {
      const item = { type: 'table', map: new Map(), path: finalPath, headered: false }
      entry.items.push(item)
      state.current = item
    } else {
      throw mkErr(lineNo, `${renderPath(finalPath)} is not an array of tables`)
    }
