}

function processLine(rawLine, lineNo, state) {
  const lp = new LineParser(rawLine, lineNo)
  lp.skipWSAndComment()
  if (lp.atEnd()) return

  if (lp.peek() === '[') {
    lp.pos++
    let isArray = false
    if (!lp.atEnd() && lp.peek() === '[') {
      isArray = true
      lp.pos++
    }
    lp.skipWSAndComment()
    const names = parseDottedName(lp)
    lp.skipWSAndComment()
    if (lp.atEnd() || lp.peek() !== ']') throw mkErr(lineNo, 'unterminated table header')
    lp.pos++
    if (isArray) {
      if (lp.atEnd() || lp.peek() !== ']') throw mkErr(lineNo, 'unterminated table header')
      lp.pos++
    }
    lp.skipWSAndComment()
    if (!lp.atEnd()) throw mkErr(lineNo, 'trailing text after a table header')
    handleHeader(state, names, isArray, lineNo)
  } else {
    const names = parseDottedName(lp)
    lp.skipWSAndComment()
    if (lp.atEnd() || lp.peek() !== '=') throw mkErr(lineNo, 'expected key = value')
    lp.pos++
    lp.skipWSAndComment()
    if (lp.atEnd()) throw mkErr(lineNo, 'expected a value')
    const fullPath = state.current.path.concat(names)
    const value = parseValue(lp, fullPath)
    lp.skipWSAndComment()
    if (!lp.atEnd()) throw mkErr(lineNo, 'trailing text after a value')
    assignDotted(state.current, names, value, lineNo)
  }
}

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  const root = { type: 'table', map: new Map(), path: [], headered: true }
  const state = { root, current: root }
  for (let i = 0; i < lines.length; i++) {
    processLine(lines[i], i + 1, state)
  }
  return root
}

